(743279, 80014, 11518, '<td valign="top">LOL are they real?  They almost look like decoys.</td>', 'LOL are they real?  They almost look like decoys.', '2004-05-31 01:17:56.000000', NULL, 1),
(743280, 80065, 21367, '<td valign="top">Cool composition.  The contrast is a little harsh for the amount of detail that we need to see.  I think lightening the sky would have helped make the cranes stand out a little better.  I might have straightened the horzion (water line) a bit more.  When ever there is water on the horizon the slightest be of tilt will make your picture feel like things are sliding off to one side.</td>', 'Cool composition.  The contrast is a little harsh for the amount of detail that we need to see.  I think lightening the sky would have helped make the cranes stand out a little better.  I might have straightened the horzion (water line) a bit more.  When ever there is water on the horizon the slightest be of tilt will make your picture feel like things are sliding off to one side.', '2004-05-31 01:18:00.000000', NULL, 1),
(743281, 80367, 14805, '<td valign="top">very cool compressed shot!</td>', 'very cool compressed shot!', '2004-05-31 01:18:07.000000', NULL, 1),
(743282, 80368, 12674, '<td valign="top">Nice color and good idea.  A bit grainy...I suggest you try Neat Image.</td>', 'Nice color and good idea.  A bit grainy...I suggest you try Neat Image.', '2004-05-31 01:18:10.000000', NULL, 1),
(743283, 80404, 14805, '<td valign="top">I love the emotion in the front one''s face.</td>', 'I love the emotion in the front one''s face.', '2004-05-31 01:18:29.000000', NULL, 1),
(743285, 79466, 14805, '<td valign="top">I see what you were going for, but I''m not a fan of this cropping. love the burn on the edges, though.</td>', 'I see what you were going for, but I''m not a fan of this cropping. love the burn on the edges, though.', '2004-05-31 01:19:03.000000', NULL, 1),
(743286, 79185, 13044, '<td valign="top">There''s a three there somewhere. Good one</td>', 'There''s a three there somewhere. Good one', '2004-05-31 01:19:16.000000', NULL, 1),
(743287, 80340, 8054, '<td valign="top">Very impressive sunset background with vibrant colors. The sails appear to be a bit out of focus. I would like to have the bottom and left trees and such cropped out as they are distracting. Just the sails and the sunset would have been a very simple yet effective presentation. Not a fan of the border, either. Overall, good effort.</td>', 'Very impressive sunset background with vibrant colors. The sails appear to be a bit out of focus. I would like to have the bottom and left trees and such cropped out as they are distracting. Just the sails and the sunset would have been a very simple yet effective presentation. Not a fan of the border, either. Overall, good effort.', '2004-05-31 01:19:32.000000', NULL, 1),
(743289, 79588, 13044, '<td valign="top">A conjuction of three planes...Good one</td>', 'A conjuction of three planes...Good one', '2004-05-31 01:20:10.000000', NULL, 1),
(743290, 80401, 11518, '<td valign="top">Wow, very nice!!!  My favourite so far.  I would like to see a landscape version instead of a portrait version.  Might not have been possible because of the restriction on "3".  I''m guessing there were more birds around.  Right?  9</td>', 'Wow, very nice!!!  My favourite so far.  I would like to see a landscape version instead of a portrait version.  Might not have been possible because of the restriction on "3".  I''m guessing there were more birds around.  Right?  9', '2004-05-31 01:20:15.000000', NULL, 1),
(743293, 80398, 8054, '<td valign="top">Nice macro setup. Lighting is too direct from above causing uneven lighting along the bottom half of the cherries. The dark shadow in the lower left is distracting and should have been cropped out.</td>', 'Nice macro setup. Lighting is too direct from above causing uneven lighting along the bottom half of the cherries. The dark shadow in the lower left is distracting and should have been cropped out.', '2004-05-31 01:21:07.000000', NULL, 1),
