(743603, 80387, 16301, '<td valign="top">A nice and simple composition that provides strength to the photo along with the negative space. Great lighting. Good luck...</td>', 'A nice and simple composition that provides strength to the photo along with the negative space. Great lighting. Good luck...', '2004-05-31 03:38:13.000000', NULL, 1),
(743607, 79726, 15511, '<td valign="top">It''s steam. Cropping out the pole &amp; tanks on the right would have cleaned this up nicely.</td>', 'It''s steam. Cropping out the pole & tanks on the right would have cleaned this up nicely.', '2004-05-31 03:43:17.000000', NULL, 1),
(743614, 80242, 20285, '<td valign="top">Awwww, 3 new kittens, soooo cute.</td>', 'Awwww, 3 new kittens, soooo cute.', '2004-05-31 04:04:59.000000', NULL, 1),
