(743627, 80264, 19952, '<td valign="top">Nice smoke! The background is more interesting than the incense sticks themselves, so I wonder if this shot would look better with more light on the sticks. Regardless, I like this shot a lot just as it is.</td>', 'Nice smoke! The background is more interesting than the incense sticks themselves, so I wonder if this shot would look better with more light on the sticks. Regardless, I like this shot a lot just as it is.', '2004-05-31 04:27:02.000000', NULL, 1),
(743628, 79588, 16301, '<td valign="top">A folded peice of paper? Did you actually type that yourself? Really good color and patterns, great job...</td>', 'A folded peice of paper? Did you actually type that yourself? Really good color and patterns, great job...', '2004-05-31 04:35:02.000000', NULL, 1),
(743629, 80272, 20285, '<td valign="top">Ha, they even ate a 3 in the leaves! Nice.</td>', 'Ha, they even ate a 3 in the leaves! Nice.', '2004-05-31 04:43:03.000000', NULL, 1),
(743631, 80215, 20285, '<td valign="top">nice</td>', 'nice', '2004-05-31 04:47:12.000000', NULL, 1),
