(743642, 79838, 10170, '<td valign="top">Awesome, and a great find for the challenge.  Great use of light here.</td>', 'Awesome, and a great find for the challenge.  Great use of light here.', '2004-05-31 05:36:18.000000', NULL, 1),
(743645, 79830, 19952, '<td valign="top">I''m sure everyone is telling you this, but without that blue line across the bottom, this is a perfect shot. You did a great job with this photo!</td>', 'I''m sure everyone is telling you this, but without that blue line across the bottom, this is a perfect shot. You did a great job with this photo!', '2004-05-31 05:38:03.000000', NULL, 1),
(743648, 80188, 10170, '<td valign="top">Simple and very effective.</td>', 'Simple and very effective.', '2004-05-31 05:39:10.000000', NULL, 1),
(743649, 79109, 15920, '<td valign="top">One of the only desaturations that I really like, probably because of the way you used the shadows.  I think this is great composition and is a ribbon pick for me.</td>', 'One of the only desaturations that I really like, probably because of the way you used the shadows.  I think this is great composition and is a ribbon pick for me.', '2004-05-31 05:40:00.000000', NULL, 1),
(743651, 80121, 10170, '<td valign="top">Beautiful, but I think it could have been more effective with less editing as it has come out too surrealistic for my taste.  Great work though.</td>', 'Beautiful, but I think it could have been more effective with less editing as it has come out too surrealistic for my taste.  Great work though.', '2004-05-31 05:41:59.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(743652, 79109, 10170, '<td valign="top">What a wonderful effect with something so simple and the right use of light.  Love it.</td>', 'What a wonderful effect with something so simple and the right use of light.  Love it.', '2004-05-31 05:42:44.000000', NULL, 1),
(743653, 79684, 10170, '<td valign="top">Simply stunning.</td>', 'Simply stunning.', '2004-05-31 05:43:30.000000', NULL, 1),
(743654, 80270, 10170, '<td valign="top">Almost there, but the focus if just that little bit off on the cherries.</td>', 'Almost there, but the focus if just that little bit off on the cherries.', '2004-05-31 05:45:58.000000', NULL, 1),
(743655, 80168, 10170, '<td valign="top">This is familiar.  I grew up in the UK, is this a 2p coin?  Nicely done regardless.</td>', 'This is familiar.  I grew up in the UK, is this a 2p coin?  Nicely done regardless.', '2004-05-31 05:48:28.000000', NULL, 1),
(743657, 80262, 10170, '<td valign="top">Absolutely beautiful.  Great composition, perfect colours.  Did you tweak the blue much or are they naturally that bright?</td>', 'Absolutely beautiful.  Great composition, perfect colours.  Did you tweak the blue much or are they naturally that bright?', '2004-05-31 05:49:34.000000', NULL, 1),
(743659, 79448, 17551, '<td valign="top">The clarity is wonderful, and I think the blue tones really work well for this shot. 9</td>', 'The clarity is wonderful, and I think the blue tones really work well for this shot. 9', '2004-05-31 05:53:08.000000', NULL, 1),
(743661, 80194, 17551, '<td valign="top">perhaps needs something a bit more animate to make the shot more interesting. The lighting could be improved to show some of the detail on the floppies, and give them some cool shadows</td>', 'perhaps needs something a bit more animate to make the shot more interesting. The lighting could be improved to show some of the detail on the floppies, and give them some cool shadows', '2004-05-31 05:54:56.000000', NULL, 1),
(743662, 80328, 17551, '<td valign="top">This is a good capture, I think it would look even better if it was a little sharper... and the detail and colours are certainly there.</td>', 'This is a good capture, I think it would look even better if it was a little sharper... and the detail and colours are certainly there.', '2004-05-31 05:55:54.000000', NULL, 1),
(743665, 80263, 17551, '<td valign="top">I guess the message is clear then ;-)</td>', 'I guess the message is clear then ;-)', '2004-05-31 05:59:36.000000', NULL, 1),
(743667, 79090, 17551, '<td valign="top">It''s hard to get a large DOF being this close (macro) to a subject, even with a very fast lens.. I''ll assume this is the effect you were after, but I keep wanting to see detail on the other snails. 6</td>', 'It''s hard to get a large DOF being this close (macro) to a subject, even with a very fast lens.. I''ll assume this is the effect you were after, but I keep wanting to see detail on the other snails. 6', '2004-05-31 06:00:53.000000', NULL, 1),
(743669, 79573, 17551, '<td valign="top">number tag seems a little outta place !</td>', 'number tag seems a little outta place !', '2004-05-31 06:01:43.000000', NULL, 1),
(743674, 80378, 17551, '<td valign="top">I like the panoramic style of this shot.. great colors too</td>', 'I like the panoramic style of this shot.. great colors too', '2004-05-31 06:04:42.000000', NULL, 1),
(743722, 80121, 806, '<td valign="top">superb! love the grace and softness. the slight motion and angle feed each other. the selective color is done beautifully! :)</td>', 'superb! love the grace and softness. the slight motion and angle feed each other. the selective color is done beautifully! :)', '2004-05-31 06:49:36.000000', NULL, 1),
(743734, 80076, 17503, '<td valign="top">nice idea, I found the pic a little too busy. try cropping closer to the single hand and maybe one stack of chips.</td>', 'nice idea, I found the pic a little too busy. try cropping closer to the single hand and maybe one stack of chips.', '2004-05-31 07:02:25.000000', NULL, 1),
(743735, 79760, 806, '<td valign="top">very pretty violas. you caught the color nicely. the background is a bit too busy. perhaps less dof would help with that. also, I think cropping a bit more on the right would be okay to exclude the "straggler". It would be okay to have your subject centered a bit more by doing that. sometimes that works.<br/>happy shooting! :)</td>', 'very pretty violas. you caught the color nicely. the background is a bit too busy. perhaps less dof would help with that. also, I think cropping a bit more on the right would be okay to exclude the "straggler". It would be okay to have your subject centered a bit more by doing that. sometimes that works.happy shooting! :)', '2004-05-31 07:05:38.000000', NULL, 1),
(743737, 80174, 806, '<td valign="top">oh my goodness! how did you ever.....?!!<br/> <br/>Please tell me that is a photo of a kitten placed behind the mice! LOL<br/>No, on second thought tell me they are all posed there, and that you are an incredible photographer! :P<br/> <br/>Okay... great background. awesome composition. lighting and exposure superb!<br/></td>', 'oh my goodness! how did you ever.....?!! Please tell me that is a photo of a kitten placed behind the mice! LOLNo, on second thought tell me they are all posed there, and that you are an incredible photographer! :P Okay... great background. awesome composition. lighting and exposure superb!', '2004-05-31 07:12:10.000000', NULL, 1),
(743738, 79726, 806, '<td valign="top">great use of time of day. love the silouette and color of the clouds and "smoke/steam"</td>', 'great use of time of day. love the silouette and color of the clouds and "smoke/steam"', '2004-05-31 07:15:49.000000', NULL, 1),
(743740, 79814, 806, '<td valign="top">the bottles have this nice fluidity/motion to them. the close up and simple background make this interesting to view.</td>', 'the bottles have this nice fluidity/motion to them. the close up and simple background make this interesting to view.', '2004-05-31 07:18:23.000000', NULL, 1),
(743741, 79665, 806, '<td valign="top">nice shot! composition and lighting are great. looks a bit too "magenta" .. did you kick up the saturation? <br/>overall a great image.</td>', 'nice shot! composition and lighting are great. looks a bit too "magenta" .. did you kick up the saturation? overall a great image.', '2004-05-31 07:24:30.000000', NULL, 1),
(743742, 79963, 806, '<td valign="top">great motion. the overall image seems noisy - perhaps underexposed. to get the motion, you must have had a slightly longer exposure though. dunno until I see your details, but based on what I see that is what I think.</td>', 'great motion. the overall image seems noisy - perhaps underexposed. to get the motion, you must have had a slightly longer exposure though. dunno until I see your details, but based on what I see that is what I think.', '2004-05-31 07:28:27.000000', NULL, 1),
(743743, 80193, 806, '<td valign="top">interesting composition. the horses on the sides seem to be "pointing" inwards to the foal - always leading to the center. nice exposure and colors.</td>', 'interesting composition. the horses on the sides seem to be "pointing" inwards to the foal - always leading to the center. nice exposure and colors.', '2004-05-31 07:30:33.000000', NULL, 1),
(743744, 80183, 806, '<td valign="top">I understand the concept. . I have kids! :)<br/> <br/>I think the dof is too shallow for most people to find the third one.. The title certainly leads you to hunt for it though.<br/> <br/>interesting point of view.</td>', 'I understand the concept. . I have kids! :) I think the dof is too shallow for most people to find the third one.. The title certainly leads you to hunt for it though. interesting point of view.', '2004-05-31 07:32:39.000000', NULL, 1),
(743745, 79838, 806, '<td valign="top">great point of view. love how the doors become a leading line to the peak of the roof pointing skyward like an arrow.<br/>nice b&amp;w treatment.<br/>interesting to view.</td>', 'great point of view. love how the doors become a leading line to the peak of the roof pointing skyward like an arrow.nice b&w treatment.interesting to view.', '2004-05-31 07:34:33.000000', NULL, 1),
(743746, 80147, 806, '<td valign="top">a bit too contrasty? or saturation?<br/>Interesting vignetting. I like the light behind them. mezmerizing stares! ;)</td>', 'a bit too contrasty? or saturation?Interesting vignetting. I like the light behind them. mezmerizing stares! ;)', '2004-05-31 07:36:00.000000', NULL, 1),
(743747, 80183, 8643, '<td valign="top">For me, you needed to get all 3 in focus for this to work.</td>', 'For me, you needed to get all 3 in focus for this to work.', '2004-05-31 07:37:18.000000', NULL, 1),
(743749, 79954, 806, '<td valign="top">superb image. the sunstar is done well, and the angle you used to make the composition wonderful. love the b&amp;w treatment to this.</td>', 'superb image. the sunstar is done well, and the angle you used to make the composition wonderful. love the b&w treatment to this.', '2004-05-31 07:38:24.000000', NULL, 1),
(743750, 79889, 806, '<td valign="top">how I''d love to put a caption to this! :)<br/> <br/>they seem so curious.</td>', 'how I''d love to put a caption to this! :) they seem so curious.', '2004-05-31 07:40:38.000000', NULL, 1),
(743751, 80121, 714, '<td valign="top">One of my favorites of this challenge.  You took a perfect shot here.  Hope you are going to make this a print.</td>', 'One of my favorites of this challenge.  You took a perfect shot here.  Hope you are going to make this a print.', '2004-05-31 07:41:51.000000', NULL, 1),
(743752, 79755, 806, '<td valign="top">fantastic vantage point/point of view.<br/>too bad about the house btw.<br/>composition, colors, action.. all interesting. would make a great addition to the local paper!</td>', 'fantastic vantage point/point of view.too bad about the house btw.composition, colors, action.. all interesting. would make a great addition to the local paper!', '2004-05-31 07:42:50.000000', NULL, 1),
