(743754, 79032, 8643, '<td valign="top">Very nicely captured, love the spalsh of colour against the white background.</td>', 'Very nicely captured, love the spalsh of colour against the white background.', '2004-05-31 07:44:01.000000', NULL, 1),
(743757, 80095, 8643, '<td valign="top">Beautiful capture, brilliantly lit, lovely clean focus and an unusual but attracive composition.  My best vote!</td>', 'Beautiful capture, brilliantly lit, lovely clean focus and an unusual but attracive composition.  My best vote!', '2004-05-31 07:45:28.000000', NULL, 1),
(743758, 79757, 806, '<td valign="top">the heavy diagonal (window? wall?) is really distracting. however, I do like the tones of the photo and the play of shadows on the floor. I can see you probably had no choice in the matter, it just makes the photo top heavy.</td>', 'the heavy diagonal (window? wall?) is really distracting. however, I do like the tones of the photo and the play of shadows on the floor. I can see you probably had no choice in the matter, it just makes the photo top heavy.', '2004-05-31 07:45:52.000000', NULL, 1),
(743759, 79814, 8643, '<td valign="top">Clever idea, well executed.</td>', 'Clever idea, well executed.', '2004-05-31 07:45:58.000000', NULL, 1),
(743761, 79784, 8643, '<td valign="top">Luck and a lot of patience must have played their part in this excellent stop motion capture.</td>', 'Luck and a lot of patience must have played their part in this excellent stop motion capture.', '2004-05-31 07:47:09.000000', NULL, 1),
