(745217, 79448, 2610, '<td valign="top">Beautiful color and details.</td>', 'Beautiful color and details.', '2004-06-01 11:10:41.000000', NULL, 1),
(745218, 79425, 19608, '<td valign="top">Magical colors.  Just enought lighting on the lamps to show a bit of detail, rather than a silhouette, which is great.  Sometime, like this, the most simple shots are the more pleasing to the eye.  Great job.</td>', 'Magical colors.  Just enought lighting on the lamps to show a bit of detail, rather than a silhouette, which is great.  Sometime, like this, the most simple shots are the more pleasing to the eye.  Great job.', '2004-06-01 11:11:23.000000', NULL, 1),
(745220, 80400, 2610, '<td valign="top">Harsh flash and shadows.  Perhaps a tripod and natural light or moving away from the subject so the flash is not so harsh would help.</td>', 'Harsh flash and shadows.  Perhaps a tripod and natural light or moving away from the subject so the flash is not so harsh would help.', '2004-06-01 11:11:38.000000', NULL, 1),
(745221, 80005, 2610, '<td valign="top">Nice photo.  The title is perfect.</td>', 'Nice photo.  The title is perfect.', '2004-06-01 11:12:06.000000', NULL, 1),
(745223, 80188, 2610, '<td valign="top">Great shadows.  A little off the top sky might be nice but that may just be personal taste.  Great warm colors.</td>', 'Great shadows.  A little off the top sky might be nice but that may just be personal taste.  Great warm colors.', '2004-06-01 11:12:51.000000', NULL, 1),
