INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(745331, 80403, 3697, '<td valign="top">I really like the color in this shot, and the composition is great. Nice work.</td>', 'I really like the color in this shot, and the composition is great. Nice work.', '2004-06-01 13:03:09.000000', NULL, 1),
(745333, 79665, 3697, '<td valign="top">If this one isn''t a ribbon winner, it will really surprise me. Composition, color, focus... all perfect.</td>', 'If this one isn''t a ribbon winner, it will really surprise me. Composition, color, focus... all perfect.', '2004-06-01 13:05:03.000000', NULL, 1),
(745337, 79235, 472, '<td valign="top">hmm - to me the main issue i have with this shot isnt the soft focus, altho that doesn''t help. it''s just that the composition doesn''t really draw my eye to any specific subject.  seems a little bit random looking, without a clear ''point''.</td>', 'hmm - to me the main issue i have with this shot isnt the soft focus, altho that doesn''t help. it''s just that the composition doesn''t really draw my eye to any specific subject.  seems a little bit random looking, without a clear ''point''.', '2004-06-01 13:10:56.000000', NULL, 1),
(745354, 80389, 772, '<td valign="top">very nicely executed... the idea is a good one for the challenge also.  This photo may have some room for improvement in the composition by cropping it a little tighter on the left and right.  The empty space isn''t really adding anything extra to the image.</td>', 'very nicely executed... the idea is a good one for the challenge also.  This photo may have some room for improvement in the composition by cropping it a little tighter on the left and right.  The empty space isn''t really adding anything extra to the image.', '2004-06-01 13:53:29.000000', NULL, 1),
(745383, 80106, 22359, '<td valign="top">I see 5 guitar''s in the whole picture ... lol</td>', 'I see 5 guitar''s in the whole picture ... lol', '2004-06-01 14:22:49.000000', NULL, 1),
(745396, 80121, 20779, '<td valign="top">My pick for the challenge. Stunning and original. Perfectly done IMHO! The strength of the calves with the floating softness -- I love this.</td>', 'My pick for the challenge. Stunning and original. Perfectly done IMHO! The strength of the calves with the floating softness -- I love this.', '2004-06-01 14:37:28.000000', NULL, 1),
(745397, 80185, 8054, '<td valign="top">Either the camera was not level or the hurdle things (I don''t know the true name for them) is not level and I suspect the latter. Either way, it give the photo an odd feel like one is going to fall over. I would also like to see more of the rider on the far left and maybe less space on the right side. You did capture nice details and colors, however.</td>', 'Either the camera was not level or the hurdle things (I don''t know the true name for them) is not level and I suspect the latter. Either way, it give the photo an odd feel like one is going to fall over. I would also like to see more of the rider on the far left and maybe less space on the right side. You did capture nice details and colors, however.', '2004-06-01 14:37:43.000000', NULL, 1),
(745399, 79720, 20779, '<td valign="top">Just when I thought I had seen all the beautiful flowers that could be done -- this one. One of my two top picks. The lighting and composition couldn''t be better.</td>', 'Just when I thought I had seen all the beautiful flowers that could be done -- this one. One of my two top picks. The lighting and composition couldn''t be better.', '2004-06-01 14:38:29.000000', NULL, 1),
(745401, 79838, 8054, '<td valign="top">Very interesting perspective and I like it as a b/w, however it looks overexposed on the right side and oversharpened.</td>', 'Very interesting perspective and I like it as a b/w, however it looks overexposed on the right side and oversharpened.', '2004-06-01 14:39:46.000000', NULL, 1),
(745402, 80100, 20779, '<td valign="top">The middle one looks lit from within, which is what makes it stand out to me. I love the completely blurred background for this one. Great shot!!</td>', 'The middle one looks lit from within, which is what makes it stand out to me. I love the completely blurred background for this one. Great shot!!', '2004-06-01 14:40:01.000000', NULL, 1),
(745406, 80197, 20779, '<td valign="top">Well done!!!</td>', 'Well done!!!', '2004-06-01 14:41:08.000000', NULL, 1),
(745407, 79490, 20779, '<td valign="top">Absolutely stunning with the blue.</td>', 'Absolutely stunning with the blue.', '2004-06-01 14:41:37.000000', NULL, 1),
(745409, 80396, 20779, '<td valign="top">Love the exposure and composition. One of my favorites this time.</td>', 'Love the exposure and composition. One of my favorites this time.', '2004-06-01 14:42:14.000000', NULL, 1),
(745410, 80238, 20779, '<td valign="top">Wish I were there! Wonderful balance.</td>', 'Wish I were there! Wonderful balance.', '2004-06-01 14:43:00.000000', NULL, 1),
(745412, 79443, 8054, '<td valign="top">Very good take on the challenge with very sharp contrast effects. It could have been cropped a bit more evenly. Compare the space between the buttons at 2 and 4 and the distance to the frame. There is much more space above 2 o''clock than at 4. Also, the background shows lots of compression and noise probably due to the long exposure.</td>', 'Very good take on the challenge with very sharp contrast effects. It could have been cropped a bit more evenly. Compare the space between the buttons at 2 and 4 and the distance to the frame. There is much more space above 2 o''clock than at 4. Also, the background shows lots of compression and noise probably due to the long exposure.', '2004-06-01 14:43:12.000000', NULL, 1),
(745414, 79963, 20779, '<td valign="top">Bet this took a lot of shots! Glad you did it!</td>', 'Bet this took a lot of shots! Glad you did it!', '2004-06-01 14:43:46.000000', NULL, 1),
(745419, 80147, 20779, '<td valign="top">Stunning shot. The expressions captured are priceless, the colors beautifully saturated and crisp, just the right DOF; I love this and think it would make a great print.</td>', 'Stunning shot. The expressions captured are priceless, the colors beautifully saturated and crisp, just the right DOF; I love this and think it would make a great print.', '2004-06-01 14:45:15.000000', NULL, 1),
(745422, 79755, 20779, '<td valign="top">What a great capture. I think you retained a perfect feel for the subject in your lighting, texture and focus.</td>', 'What a great capture. I think you retained a perfect feel for the subject in your lighting, texture and focus.', '2004-06-01 14:46:54.000000', NULL, 1),
(745424, 79892, 21087, '<td valign="top">I like this picture. Well-observed, good composition (though rather a lot of space in the foreground). However, I would probably have waited until those people on the path were out of the picture. Eliminating them would have increased the feeling of isolation.</td>', 'I like this picture. Well-observed, good composition (though rather a lot of space in the foreground). However, I would probably have waited until those people on the path were out of the picture. Eliminating them would have increased the feeling of isolation.', '2004-06-01 14:47:35.000000', NULL, 1),
(745427, 80122, 8054, '<td valign="top">I think I know who took this shot but I will reserve that for later as I think these are the windmills in NorCal. Anywho, great shot and looks great in b/w. A small bit of compression and maybe a little bit of oversharpening but great contrast with the white clouds and windmills against the hills. 7</td>', 'I think I know who took this shot but I will reserve that for later as I think these are the windmills in NorCal. Anywho, great shot and looks great in b/w. A small bit of compression and maybe a little bit of oversharpening but great contrast with the white clouds and windmills against the hills. 7', '2004-06-01 14:47:51.000000', NULL, 1),
(745428, 80122, 20779, '<td valign="top">The B &amp; W works perfectly for this.</td>', 'The B & W works perfectly for this.', '2004-06-01 14:47:54.000000', NULL, 1),
(745431, 79235, 20779, '<td valign="top">I really like the soft, velvety texture here. A sharper focus would take away from anything special being evoked.</td>', 'I really like the soft, velvety texture here. A sharper focus would take away from anything special being evoked.', '2004-06-01 14:49:12.000000', NULL, 1),
(745433, 79513, 20779, '<td valign="top">A classis well done.</td>', 'A classis well done.', '2004-06-01 14:49:37.000000', NULL, 1),
(745434, 80403, 8054, '<td valign="top">Very nice entry. Nice gradient background and clear details of the fruit and excellent neg space. My only concern is the thickness of the border. Such a delicate entry needs a thinner border, imo. 7</td>', 'Very nice entry. Nice gradient background and clear details of the fruit and excellent neg space. My only concern is the thickness of the border. Such a delicate entry needs a thinner border, imo. 7', '2004-06-01 14:49:52.000000', NULL, 1),
(745435, 80007, 20779, '<td valign="top">Beautiful luminous feel to the husks make this special.</td>', 'Beautiful luminous feel to the husks make this special.', '2004-06-01 14:50:30.000000', NULL, 1),
(745437, 79720, 8054, '<td valign="top">Although excellent in its current composition, I think it would have been better with the sky as the background/neg space vs trees and other daisies.</td>', 'Although excellent in its current composition, I think it would have been better with the sky as the background/neg space vs trees and other daisies.', '2004-06-01 14:51:41.000000', NULL, 1),
(745439, 79609, 20779, '<td valign="top">I really like the cropping and arrangement. The highlight at the front is just the right accent in my opinion. The colors and grains all work together.</td>', 'I really like the cropping and arrangement. The highlight at the front is just the right accent in my opinion. The colors and grains all work together.', '2004-06-01 14:52:08.000000', NULL, 1),
(745440, 79575, 20779, '<td valign="top">Stunning clarity and colors. I think I may have liked a less tight crop possibly.</td>', 'Stunning clarity and colors. I think I may have liked a less tight crop possibly.', '2004-06-01 14:53:13.000000', NULL, 1),
(745444, 79214, 20779, '<td valign="top">Great "movement" in the composition. To make it "pop" a bit more, maybe a sharper focus and focal of interest or background?</td>', 'Great "movement" in the composition. To make it "pop" a bit more, maybe a sharper focus and focal of interest or background?', '2004-06-01 14:55:04.000000', NULL, 1),
(745447, 79374, 20779, '<td valign="top">I like the geometric composition and its being off to the right. I think it might pop a little more with a crisper contrast/lighting and a stronger focus of interest. I am seeing a lot of "jaggies", but not sure if you were wanting a rougher texture maybe.</td>', 'I like the geometric composition and its being off to the right. I think it might pop a little more with a crisper contrast/lighting and a stronger focus of interest. I am seeing a lot of "jaggies", but not sure if you were wanting a rougher texture maybe.', '2004-06-01 14:57:15.000000', NULL, 1),
(745450, 80277, 20779, '<td valign="top">Nice composition and focal point. I would like to see a little more contrast and crispness for this.</td>', 'Nice composition and focal point. I would like to see a little more contrast and crispness for this.', '2004-06-01 14:59:02.000000', NULL, 1),
(745455, 79101, 20779, '<td valign="top">I may not be getting something it; I can''t see a composition here or the connection to the challenge.</td>', 'I may not be getting something it; I can''t see a composition here or the connection to the challenge.', '2004-06-01 15:01:40.000000', NULL, 1),
(745459, 80034, 20779, '<td valign="top">I like the idea and beautiful skies. I think I would straighten it and crop a bit more selectively.</td>', 'I like the idea and beautiful skies. I think I would straighten it and crop a bit more selectively.', '2004-06-01 15:02:51.000000', NULL, 1),
(745462, 79791, 20779, '<td valign="top">Great capture for the challenge. I would like to see a bit sharper focus. The leaves in the foreground are distracting as a blur and I would prefer a bit stronger focal/interest point (which is hard to find when you have no control over the situation, I know).</td>', 'Great capture for the challenge. I would like to see a bit sharper focus. The leaves in the foreground are distracting as a blur and I would prefer a bit stronger focal/interest point (which is hard to find when you have no control over the situation, I know).', '2004-06-01 15:05:44.000000', NULL, 1),
(745463, 79109, 8054, '<td valign="top">Vitamin E capules? Very creative! Love the transparency/translucency effect you have with the capsules themselves. My nitpicky complaint is with the reflected (refracted?) white light not all being even. The top one is shorter and abruptly cutoff while the other two fade nicely. 7</td>', 'Vitamin E capules? Very creative! Love the transparency/translucency effect you have with the capsules themselves. My nitpicky complaint is with the reflected (refracted?) white light not all being even. The top one is shorter and abruptly cutoff while the other two fade nicely. 7', '2004-06-01 15:06:11.000000', NULL, 1),
(745467, 79302, 20779, '<td valign="top">Interesting composition and colors. I would score it higher with a less htight crop, sharper focus/contrast, and maybe a little more negative space.</td>', 'Interesting composition and colors. I would score it higher with a less htight crop, sharper focus/contrast, and maybe a little more negative space.', '2004-06-01 15:07:16.000000', NULL, 1),
(745471, 80329, 20779, '<td valign="top">Very cute little guys. I think I would have scored it higher with a lesser crop and more negative space possibly. Focus could use a little sharpening.</td>', 'Very cute little guys. I think I would have scored it higher with a lesser crop and more negative space possibly. Focus could use a little sharpening.', '2004-06-01 15:08:58.000000', NULL, 1),
(745474, 80168, 20779, '<td valign="top">Wonderfull detail and light; I think a more interesting composition might have been with a less-tight crop and focus of interest.</td>', 'Wonderfull detail and light; I think a more interesting composition might have been with a less-tight crop and focus of interest.', '2004-06-01 15:10:19.000000', NULL, 1),
(745476, 80007, 8054, '<td valign="top">Mmmm...I love corn! Nice even lighting (for the most part) and amazing details of the husk, silk and kernels. The only area with bright lighting is behind the husk in the upper right. 8</td>', 'Mmmm...I love corn! Nice even lighting (for the most part) and amazing details of the husk, silk and kernels. The only area with bright lighting is behind the husk in the upper right. 8', '2004-06-01 15:11:44.000000', NULL, 1),
(745477, 80328, 20779, '<td valign="top">Probably partly due to "taste" (not crazy about insects), but from a composition standpoint, I would have liked it better with sharper focus, higher contrast/colors, and less of a crop I think.</td>', 'Probably partly due to "taste" (not crazy about insects), but from a composition standpoint, I would have liked it better with sharper focus, higher contrast/colors, and less of a crop I think.', '2004-06-01 15:12:01.000000', NULL, 1),
(745479, 80243, 20779, '<td valign="top">Interesting selection of subjects. I would have liked a sharper focus and focal point of interest I think.</td>', 'Interesting selection of subjects. I would have liked a sharper focus and focal point of interest I think.', '2004-06-01 15:13:25.000000', NULL, 1),
(745480, 80262, 20779, '<td valign="top">Beautiful blue chosen and great arrangement within the frame. I think in this particular case, the blue might be too bright for the soft background.</td>', 'Beautiful blue chosen and great arrangement within the frame. I think in this particular case, the blue might be too bright for the soft background.', '2004-06-01 15:14:49.000000', NULL, 1),
(745481, 80014, 8054, '<td valign="top">This could use some additional cropping. The top could get some lopped off just below the darker area of the water. That would give the water texture consistency throughout the photo. In the upper left there is a white spot that should have been cloned out. Also, I would like to have seen more cushion space on the left side of the left bird, enough so it would be equal to the amount on the right side. Contrast, colors and details of the birds and water is very good.</td>', 'This could use some additional cropping. The top could get some lopped off just below the darker area of the water. That would give the water texture consistency throughout the photo. In the upper left there is a white spot that should have been cloned out. Also, I would like to have seen more cushion space on the left side of the left bird, enough so it would be equal to the amount on the right side. Contrast, colors and details of the birds and water is very good.', '2004-06-01 15:15:18.000000', NULL, 1),
(745484, 79873, 20779, '<td valign="top">Very serene scene captured. I think it would really pop with a "subject of interest", maybe on one of the benches?</td>', 'Very serene scene captured. I think it would really pop with a "subject of interest", maybe on one of the benches?', '2004-06-01 15:15:51.000000', NULL, 1),
(745485, 79620, 20779, '<td valign="top">Love these in the portrait mode. I may have preferred a slightly more contrasting background for the flowers to stand against.</td>', 'Love these in the portrait mode. I may have preferred a slightly more contrasting background for the flowers to stand against.', '2004-06-01 15:16:58.000000', NULL, 1),
(745488, 79588, 20779, '<td valign="top">Very cool idea. I would have liked a bit more focus and the focal point a little stronger.</td>', 'Very cool idea. I would have liked a bit more focus and the focal point a little stronger.', '2004-06-01 15:18:20.000000', NULL, 1),
(745489, 79185, 20779, '<td valign="top">Love the spring green! I would have liked a little less solid balck areas inter-mixed if possible.</td>', 'Love the spring green! I would have liked a little less solid balck areas inter-mixed if possible.', '2004-06-01 15:19:32.000000', NULL, 1),
(745492, 80014, 20779, '<td valign="top">Great capture, and I like the soft feel of the water. A bit less cropping I think might have made the geese stand out more and shown off more of the beautiful water.</td>', 'Great capture, and I like the soft feel of the water. A bit less cropping I think might have made the geese stand out more and shown off more of the beautiful water.', '2004-06-01 15:20:55.000000', NULL, 1),
(745493, 80253, 327, '<td valign="top">7- from me. Nice clean focus and good light control.</td>', '7- from me. Nice clean focus and good light control.', '2004-06-01 15:21:42.000000', NULL, 1),
(745494, 80123, 20779, '<td valign="top">Cool idea! I would have maybe straigtened a bit more and cropped a little less. I think I might like it more without the border or a darker one perhaps.</td>', 'Cool idea! I would have maybe straigtened a bit more and cropped a little less. I think I might like it more without the border or a darker one perhaps.', '2004-06-01 15:22:22.000000', NULL, 1),
(745495, 78955, 327, '<td valign="top">Very pretty light, tones and focus. I do question the tight crop on the right side?  7 from me. Good luck.</td>', 'Very pretty light, tones and focus. I do question the tight crop on the right side?  7 from me. Good luck.', '2004-06-01 15:22:36.000000', NULL, 1),
(745496, 79755, 327, '<td valign="top">Beautiful composition, light and focus. Right on for the challenge also. Well done. 7</td>', 'Beautiful composition, light and focus. Right on for the challenge also. Well done. 7', '2004-06-01 15:23:11.000000', NULL, 1),
(745497, 80140, 20779, '<td valign="top">Adorable shot and I love the two tone. I think I would have liked a little less red area; maybe just the cap?</td>', 'Adorable shot and I love the two tone. I think I would have liked a little less red area; maybe just the cap?', '2004-06-01 15:23:57.000000', NULL, 1),
(745500, 79609, 327, '<td valign="top">I like this idea, the use of ''rule of thirds''.....but this is a little dark in spots. In other words the light looks too uneven. The crop on the right is really tight. Any way the focus is good, the idea is good. Good luck to ya. 6</td>', 'I like this idea, the use of ''rule of thirds''.....but this is a little dark in spots. In other words the light looks too uneven. The crop on the right is really tight. Any way the focus is good, the idea is good. Good luck to ya. 6', '2004-06-01 15:24:50.000000', NULL, 1),
(745502, 79280, 11895, '<td valign="top">nice image, fits the topic well, but a neutral background color would have added some definition to the donuts</td>', 'nice image, fits the topic well, but a neutral background color would have added some definition to the donuts', '2004-06-01 15:26:16.000000', NULL, 1),
(745507, 79280, 327, '<td valign="top">Yum. Hey these really made a nice colorful shot. I think your focus could of been a bit more sharp. Other then that this is a nice entry. Good luck.</td>', 'Yum. Hey these really made a nice colorful shot. I think your focus could of been a bit more sharp. Other then that this is a nice entry. Good luck.', '2004-06-01 15:28:53.000000', NULL, 1),
