(745511, 80204, 327, '<td valign="top">That is really an awesome light post. Very pretty and a good shot. Maybe a bit over sharpened.</td>', 'That is really an awesome light post. Very pretty and a good shot. Maybe a bit over sharpened.', '2004-06-01 15:30:20.000000', NULL, 1),
(745520, 79726, 11895, '<td valign="top">I think this is too dark, has too much solid black area; adjusting exposure or lightening in post processing to give some details in the black would have improved it, or perhaps crop the bottom and emphasize the sky a bit more</td>', 'I think this is too dark, has too much solid black area; adjusting exposure or lightening in post processing to give some details in the black would have improved it, or perhaps crop the bottom and emphasize the sky a bit more', '2004-06-01 15:34:25.000000', NULL, 1),
(745526, 80183, 16965, '<td valign="top">The pigeons at the top are Really hard to spot...and I''m only assuming that those are pigeons!  Great DOF, but a deeper one would have suited this challenge better.</td>', 'The pigeons at the top are Really hard to spot...and I''m only assuming that those are pigeons!  Great DOF, but a deeper one would have suited this challenge better.', '2004-06-01 15:37:51.000000', NULL, 1),
(745543, 80280, 11895, '<td valign="top">very good image but I think it may have looked better if cropped so that the uncarved stone did not show in the upper left corner; wise choice for this challenge</td>', 'very good image but I think it may have looked better if cropped so that the uncarved stone did not show in the upper left corner; wise choice for this challenge', '2004-06-01 15:47:11.000000', NULL, 1),
(745601, 79740, 327, '<td valign="top">Pretty, prue, clean colors and lighting. nice!</td>', 'Pretty, prue, clean colors and lighting. nice!', '2004-06-01 16:53:20.000000', NULL, 1),
