(751244, 80204, 10268, '<td valign="top">Seems pretty flat.</td>', 'Seems pretty flat.', '2004-06-05 08:00:23.000000', NULL, 1),
(751245, 79059, 10268, '<td valign="top">I see six things, not three.<br/> <br/> <br/> <br/> <br/> <br/> <br/> <br/> <br/>Kidding.  Haha.  I''m probably not funny.  Anyway, I like this a lot.  It has a great mood, good contrast and DoF. 8.</td>', 'I see six things, not three.        Kidding.  Haha.  I''m probably not funny.  Anyway, I like this a lot.  It has a great mood, good contrast and DoF. 8.', '2004-06-05 08:01:56.000000', NULL, 1),
